message.content:
{
  "title": "Through the Ruined Gates",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Massive iron gates lie twisted and half-buried in rubble, with faded royal banners torn and flapping in the wind. Mara the Cartographer studies a map while the Glass Diver adjusts his helmet.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of hidden dangers ahead.",
      "visual_description": "Inside the gate courtyard, the Oracle Lamp flickers atop a broken pillar, its single eye narrowing as it speaks. Tin Fox sniffs the ground cautiously.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "They find the Sleeping Tax Collector in a collapsed guardhouse.",
      "visual_description": "Under a sagging roof, the Sleeping Tax Collector snores with his head on a ledger book, stamped papers stuck to his sleeves. Mara nudges him awake.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The collector mumbles about a cursed tower.",
      "visual_description": "Bleary-eyed, the Sleeping Tax Collector points a trembling finger toward a spire wrapped in thorny vines. The Oracle Lamp casts a warning red glow.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "The Glass Diver scouts through a shattered window.",
      "visual_description": "The Glass Diver swims through a broken stained-glass window, emerging into a dark hall where cobwebs drape old chandeliers. Tin Fox waits outside.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara deciphers a hidden passage on her map.",
      "visual_description": "Kneeling by a fountain choked with dead leaves, Mara traces a new route with ink-stained fingers. The Oracle Lamp hovers close, illuminating the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox triggers a pressure plate, opening a magic door.",
      "visual_description": "The small clockwork fox steps on a loose stone, and a wall grinds open to reveal a glowing doorway etched with runes. The party gathers around.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "They enter a throne room filled with illusionary treasures.",
      "visual_description": "Golden coins and jewels float in midair, shimmering like mirages. The Oracle Lamp warns they are traps, while the Sleeping Tax Collector reaches sleepily for a coin.",
      "characters": ["oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The Glass Diver navigates a mirror maze.",
      "visual_description": "Reflections of the rescuer multiply in endless mirrors, his diving helmet glowing with fractured light. He finds the true path by tapping the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara corrects their course using a star chart.",
      "visual_description": "Under a collapsed dome open to the sky, Mara aligns her brass compass with a constellation. Tin Fox watches, its blue eyes reflecting the stars.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "They encounter a sealed door that only opens to a riddle.",
      "visual_description": "A massive stone door carved with ancient script blocks the hallway. The Oracle Lamp reads the riddle aloud, its flame flickering with each syllable.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector accidentally solves the riddle.",
      "visual_description": "Muttering nonsense in his sleep, the collector blurts the answer. The door groans open, revealing a staircase downward. Everyone stares in disbelief.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They descend into a dungeon with barred cells.",
      "visual_description": "Damp stone corridors lined with iron bars stretch ahead. The Glass Diver peers into a cell, seeing only old bones and a rusted key on the floor.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox retrieves the key, dodging a falling portcullis.",
      "visual_description": "The clockwork fox zips under a descending grate, grabbing the key with its jaws just in time. It returns, tail wagging with a whir of gears.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "They unlock a chamber containing the final door.",
      "visual_description": "The key opens an ornate door to a room with a massive iron portal at the far end. The Oracle Lamp glows bright, sensing their goal is near.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver swims through a window into the escape corridor.",
      "visual_description": "Using his ability, the Glass Diver phases through a barred window and unlocks the final door from inside. The others rush through.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They flee across a crumbling bridge under a red sky.",
      "visual_description": "A stone bridge spans a chasm, with loose stones falling into the abyss. The party runs single file, the Oracle Lamp casting a path of light ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side as the bridge collapses behind them.",
      "visual_description": "The final stone falls as they leap onto solid ground. The ruined city smolders in the distance. Mara marks the route complete on her map.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "1pFjxoaZxHOoHD0O1TCaWg"
}

